import json
from pathlib import Path

p = Path(__file__).resolve().parent / 'translations/ro/full/chunks/0007.json'
d = json.loads(p.read_text())
translations = {
    't000040': 'Într-o epocă a progresului tehnologic rapid și a incertitudinii economice, Bitcoin apare ca o forță revoluționară care contestă concepțiile tradiționale despre bani și valoare. Această monedă digitală nu este doar o tendință trecătoare, ci o inovație importantă care poate remodela peisajul financiar. Un aspect esențial al Bitcoin este capacitatea sa de a servi drept rezervă de valoare. Spre deosebire de monedele fiduciare, expuse inflației și manipulării, oferta Bitcoin este limitată la 21 de milioane de unități, asemănător metalelor prețioase precum aurul. Această raritate îl face o alternativă atrăgătoare pentru cei care vor să își protejeze averea într-un mediu economic volatil. Descentralizarea Bitcoin îi sporește atractivitatea. Într-o lume tot mai neîncrezătoare în instituțiile financiare centralizate, Bitcoin oferă o metodă transparentă și sigură de a efectua tranzacții fără intermediari.',
    't000041': 'Acest lucru le permite oamenilor să își controleze propriul viitor financiar, favorizează o incluziune financiară mai largă și permite participarea la economia globală fără dependență de politicile guvernamentale. Tehnologia pe care se bazează Bitcoin — blockchain-ul — deschide o nouă epocă a tranzacțiilor financiare. Transparența și imposibilitatea modificării înregistrărilor oferă un nivel de securitate fără precedent, înlătură multe ineficiențe ale sistemelor tradiționale și încurajează responsabilitatea. Astfel, Bitcoin reprezintă o schimbare mai amplă către un viitor financiar mai echitabil. Totuși, Bitcoin se confruntă cu provocări legate de impactul asupra mediului, scalabilitate și cadrul de reglementare. Dezvoltările continue din ecosistem arată însă preocuparea de a aborda aceste probleme și întăresc potențialul Bitcoin de a evolua și de a răspunde cerințelor unei lumi în schimbare. Analiza complexității finanțelor moderne prezintă Bitcoin drept o alternativă convingătoare la sistemele monetare tradiționale, afectate în trecut de instabilitate.',
    't000042': 'Caracteristicile sale distincte îl poziționează ca activ valoros, care le permite oamenilor să își protejeze și să își sporească averea, făcând legătura între practicile monetare din trecut și cele ale viitorului. La capătul explorării noastre, este limpede că înțelegerea Bitcoin și a implicațiilor sale este esențială în peisajul financiar de astăzi, aflat în schimbare rapidă. The Bitcoin Standard: The Decentralized Alternative to Central Banking, de Saifedean Ammous, oferă perspective valoroase asupra acestei monede revoluționare și îi îndeamnă pe cititori să regândească noțiunile tradiționale de bani și valoare. Viziunea Bitcoin, inițiată de enigmaticul Satoshi Nakamoto, reprezintă o schimbare importantă către descentralizare și suveranitate financiară personală. Prin lansarea Bitcoin în 2009, Nakamoto a urmărit să le ofere oamenilor posibilitatea de a-și controla propriul destin financiar, fără să depindă de instituții centralizate. Această idee fondatoare are un ecou puternic într-o lume în care încrederea în sistemele bancare tradiționale este adesea pusă la îndoială.',
    't000043': 'Citind argumentele și analizele convingătoare ale lui Ammous, vei descoperi nu doar mecanismele Bitcoin, ci și potențialul lui de a redefini relația noastră cu banii și de a spori autonomia economică. Această explorare a lumii Bitcoin nu privește doar o monedă digitală; ea vorbește despre un viitor în care autonomia și siguranța financiară devin accesibile. Lectura acestei cărți ar putea fi poarta ta către înțelegerea puterii transformatoare a Bitcoin și a felului în care ți-ar putea modela viitorul financiar.',
    't000044': 'Bibliografie',
    't000045': 'Ammous, S. (2018). The Bitcoin Standard: The decentralized alternative to central banking (E. C. P. R. G. Ed.). Wiley.',
    't000046': 'Nakamoto, S. (2008). Bitcoin: A peer-to-peer electronic cash system. Accesat de la https://bitcoin.org/bitcoin.pdf.',
}
for segment in d['segments']:
    segment['translation'] = translations[segment['id']]
p.write_text(json.dumps(d, ensure_ascii=False, indent=2) + '\n')
